import { faBars, faChevronDown } from "@fortawesome/free-solid-svg-icons";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import * as React from "react";
import { Col, Container, Row } from "react-bootstrap";
import { NavLink } from "react-router-dom";
import styled from "styled-components";
import NuevoFoundationLogo from "../../../assets/logos/Logo_long.svg";
import { Const } from "../../../Const";
import { NavItems, INavItem } from "./NavItems";
import { useLocation } from 'react-router-dom';

import {
  faFacebookF,
  faInstagram,
  faXTwitter,
  faLinkedin,
  faYoutube,
  faSpotify,
  faGithub
} from "@fortawesome/free-brands-svg-icons";

import { faStore } from "@fortawesome/free-solid-svg-icons";

const AboveHeaderContainer = styled.div`
  display: flex;
  align-items: center;
  justify-content: flex-end;
  height: 32px;
  padding-right: 20px;
  font-family: "Lato", sans-serif;
  font-weight: bold;
  background-color: #ECECEC;
  font-size: 16px;
  color: #000000;
`;

const AboveHeaderItem = styled.div`
  padding-left: 25px;
`;

const AboveHeaderLink = styled.a`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  min-height: 24px;
  border-radius: 2px;
  color: #000000;

  &:focus,
  &:hover,
  &:visited,
  &:link,
  &:active {
    text-decoration: none;
    color: #000000;
  }

  &:focus-visible {
    outline: 3px solid #005ea8;
    outline-offset: 2px;
  }
`;

const HeaderWrapper = styled.div`
  height: 72px;
  font-family: "lato-semibold", sans-serif;
  color: #707070;
  font-size: 16px;
  background-color: #ffffff;
`;

const NavLogo = styled.img`
  float: left;
`;

const NavList = styled.ul`
  float: right;
  text-align: center;
  padding-top: 20px;
  margin-bottom: 0;
  background-color: #ffffff;
`;

const NavItem = styled.li`
  display: inline-block;
  padding-right: 50px;
  cursor: pointer;
  &::after {
    content: "";
    display: block;
    width: 0;
    height: 4px;
    background: #fcc600;
    transition: width 0.3s;
    margin-top: 5px;
  }

  &:hover {
    color: #000000;
  }

  &:hover::after {
    width: 100%;
  }
`;

const ActiveNavItem = styled.li`
  display: inline-block;
  padding-right: 50px;
  cursor: pointer;
  color: #000000;

  span {
    display: block;
    border-top: 4px solid #fcc600;
    margin-top: 5px;
  }
`;

const NavIcon = styled.span`
  padding-left: 10px;
`;

const StyledExternalLink = styled.a`
  display: inline-block;
  color: #535353;
  background-color: #ffffff;
  text-decoration: none;

  &:focus,
  &:hover,
  &:visited,
  &:link,
  &:active {
    color: #535353;
    background-color: #ffffff;
    text-decoration: none;
  }

  &:focus-visible {
    outline: 3px solid #005ea8;
    outline-offset: 3px;
  }
`

const StyledNavLink = styled(NavLink)`
  display: inline-block;
  color: #535353;
  background-color: #ffffff;
  text-decoration: none;

  &:focus,
  &:hover,
  &:visited,
  &:link,
  &:active {
    color: #535353;
    background-color: #ffffff;
    text-decoration: none;
  }

  &:focus-visible {
    outline: 3px solid #005ea8;
    outline-offset: 3px;
  }
`;

interface IHeaderProps {
  hamburgerMenuOpen: boolean;
  handleHamburgerIconClick: () => void;
}

interface IHeaderPropsWithRouter extends IHeaderProps {
  location: { pathname: string };
}

export class Header extends React.Component<IHeaderPropsWithRouter> {
  public renderNavItems(): JSX.Element[] {
    return NavItems.map((navItem: INavItem, index: number) => {
      const isActive = !navItem.external && navItem.link === this.props.location.pathname;
      const content = (
        <>
          {navItem.text}
          {navItem.dropdown && (
            <NavIcon>
              <FontAwesomeIcon icon={faChevronDown} className={"fa-sm"} />
            </NavIcon>
          )}
          {isActive && <span />}
        </>
      );
      const itemContent = navItem.external ? (
        <StyledExternalLink href={navItem.link}>{content}</StyledExternalLink>
      ) : (
        <StyledNavLink to={navItem.link}>{content}</StyledNavLink>
      );

      return isActive ? (
        <ActiveNavItem key={index}>{itemContent}</ActiveNavItem>
      ) : (
        <NavItem key={index}>{itemContent}</NavItem>
      );
    });
  }

  public render() {
    return (

        <Container fluid={true}>
          <Row>
            <Col xs={12}>
              <AboveHeaderContainer>
                <AboveHeaderItem>
                  <AboveHeaderLink
                      target="_blank"
                      rel="noopener noreferrer"
                      href="https://www.instagram.com/nuevofoundation"
                      aria-label="Nuevo Foundation on Instagram"
                  >
                    <FontAwesomeIcon icon={faInstagram} className={"fa-1x"} />
                  </AboveHeaderLink>
                </AboveHeaderItem>
                <AboveHeaderItem>
                  <AboveHeaderLink
                      target="_blank"
                      rel="noopener noreferrer"
                      href="https://twitter.com/nuevofoundation"
                      aria-label="Nuevo Foundation on X"
                  >
                    <FontAwesomeIcon icon={faXTwitter} className={"fa-1x"} />
                  </AboveHeaderLink>
                </AboveHeaderItem>
                <AboveHeaderItem>
                  <AboveHeaderLink
                      target="_blank"
                      rel="noopener noreferrer"
                      href="https://www.facebook.com/NuevoFoundation"
                      aria-label="Nuevo Foundation on Facebook"
                  >
                    <FontAwesomeIcon icon={faFacebookF} className={"fa-1x"} />
                  </AboveHeaderLink>
                </AboveHeaderItem>
                <AboveHeaderItem>
                  <AboveHeaderLink
                      target="_blank"
                      rel="noopener noreferrer"
                      href="https://www.linkedin.com/company/nuevofoundation"
                      aria-label="Nuevo Foundation on LinkedIn"
                  >
                    <FontAwesomeIcon icon={faLinkedin} className={"fa-1x"} />
                  </AboveHeaderLink>
                </AboveHeaderItem>
                <AboveHeaderItem>
                  <AboveHeaderLink
                      target="_blank"
                      rel="noopener noreferrer"
                      href="https://www.youtube.com/nuevofoundation?sub_confirmation=1"
                      aria-label="Nuevo Foundation on YouTube"
                  >
                    <FontAwesomeIcon icon={faYoutube} className={"fa-1x"} />
                  </AboveHeaderLink>
                </AboveHeaderItem>
                <AboveHeaderItem>
                  <AboveHeaderLink
                      target="_blank"
                      rel="noopener noreferrer"
                      href="https://open.spotify.com/playlist/0uQ8AwLs4SIpY4A4G52pTB?si=e30542420a8c40b1"
                      aria-label="Nuevo Foundation on Spotify"
                  >
                    <FontAwesomeIcon icon={faSpotify} className={"fa-1x"} />
                  </AboveHeaderLink>
                </AboveHeaderItem>
                <AboveHeaderItem>
                  <AboveHeaderLink
                      target="_blank"
                      rel="noopener noreferrer"
                      href="https://github.com/NuevoFoundation"
                      aria-label="Nuevo Foundation on GitHub"
                  >
                    <FontAwesomeIcon icon={faGithub} className={"fa-1x"} />
                  </AboveHeaderLink>
                </AboveHeaderItem>
                 <AboveHeaderItem>
                  <AboveHeaderLink
                      target="_blank"
                      rel="noopener noreferrer"
                      href="https://www.stickermule.com/nuevofoundation"
                      aria-label="Nuevo Foundation store"
                  >
                    <FontAwesomeIcon icon={faStore} className={"fa-1x"} />
                  </AboveHeaderLink>
                </AboveHeaderItem>
                <AboveHeaderItem>
                  <AboveHeaderLink
                      rel="noopener noreferrer"
                      href={Const.SupportUsPage}
                  >
                    Donate
                  </AboveHeaderLink>
                </AboveHeaderItem>
              </AboveHeaderContainer>
            </Col>
          </Row>
          <Row>
            <Col sm={12} className="d-none d-sm-block">
              <HeaderWrapper>
                <StyledNavLink to={"/"}>
                  <NavLogo src={NuevoFoundationLogo} height={"60px"} alt="Nuevo Foundation home" />
                </StyledNavLink>
                <NavList> {this.renderNavItems()} </NavList>
              </HeaderWrapper>
            </Col>
            {/* <Col sm={12} xsHidden={true}>
            <ButtonWrapper>
              <AuthContext.Consumer>
                {({ memberAuthenticated, toggleAuthentication, memberAuthenticatedName }) => (
                  memberAuthenticated ?
                    <div><StyledNavLink to={`/members/${JwtTokenHelper.decodeMemberId(SessionStorageHelper.GetJwt()!.token)}`}>Welcome, {memberAuthenticatedName}!</StyledNavLink> | <StyledSpan onClick={toggleAuthentication}>Logout</StyledSpan></div>
                    :
                    <AuthenticationModal toggleAuthentication={toggleAuthentication}>
                      <ButtonCta
                        text={"REGISTER"}
                        backgroundColor={"#FFFFFF"}
                        textColor={"#000000"}
                        border={"4px solid #fcca13"}
                      />
                    </AuthenticationModal>
                )}
              </AuthContext.Consumer>
            </ButtonWrapper>
                </Col> */}
            <Col xs={12} className="d-block d-sm-none">
              <Row>
                <Col xs={10}>
                  <StyledNavLink to={"/"}>
                    <NavLogo src={NuevoFoundationLogo} height={"60%"} alt="Nuevo Foundation home" />
                  </StyledNavLink>
                </Col>
                <Col
                    onClick={this.props.handleHamburgerIconClick}
                    xs={2}
                    style={{
                      paddingTop: "4%",
                      paddingLeft: "4%",
                      cursor: "pointer"
                    }}
                >
                  <FontAwesomeIcon icon={faBars} className={"fa-lg"} />
                </Col>
              </Row>
            </Col>
          </Row>
        </Container>
    );
  }
}

function HeaderWithRouter(props: IHeaderProps) {
  const location = useLocation();
  return <Header {...props} location={location} />;
}

export default HeaderWithRouter;
